using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "AreaPurifyCorruptEffectCustomTag", menuName = "Data/Battle/Battle Actions/Tags/AreaPurifyCorruptEffectCustomTag", order = 0)]
public class AreaPurifyCorruptEffectCustomTag : Tag
{
	[SerializeField]
	private AreaPurifyCorruptEffect areaPurifyCorruptEffect;

	public override string GetTagDescription()
	{
		BattleAction battleAction = areaPurifyCorruptEffect.BattleAction;
		if (areaPurifyCorruptEffect.Wave)
		{
			return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(tagID + "_D"), battleAction.GetActionDescription(-1).RemoveLast(), ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedThenEnemyLoseAllEffect(areaPurifyCorruptEffect));
		}
		if (areaPurifyCorruptEffect.RadiantBomb)
		{
			return Smart.Format(base.GetTagDescription(), battleAction.GetActionDescription(-1));
		}
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedWhenEnemyDefeatedTagBase(), areaPurifyCorruptEffect.GetEffectName(), battleAction.GetActionDescription(-1));
	}
}
